  str_n32_multiline_18_name = "Montague",
  str_n32_multiline_19_name = "chica pelirroja",
  str_n32_multiline_20_name = "Señorita roshee",
  str_n32_multiline_21_name = "papelería carta",
  str_n32_multiline_22_name = "No eres tu",
  str_n32_multiline_23_name = "Casa Montague",
  str_n32_multiline_24_name = "Profecía",
  str_n32_multiline_1_name_desc = "Joshua se transforma en un monstruo y te ataca. Jakine lanza apresuradamente un hechizo para teletransportar a todos fuera del Cristal de la Memoria Eterna, y cuando recuperas el sentido...",
  str_n32_multiline_2_name_desc = "—",
  str_n32_multiline_3_name_desc = "Se separan para tomar dos caminos separados, de acuerdo con el plan, y esperan a la Oscuridad. Angel a aparecer. Sin embargo, las cosas casi nunca son tan simples ahora, ¿verdad?",
  str_n32_multiline_4_name_desc = "Un dragón negro como la brea y el espeluznante ejército rebelde... Un buen espectáculo está a punto de comenzar.",
  str_n32_multiline_5_name_desc = "El tiempo vuelve a fluir hacia atrás, los viejos recuerdos y nuevos obstáculos esperan tu llegada.",
  str_n32_multiline_6_name_desc = "Tu fiesta se reúne con Lady Joshua de nuevo, pero la historia da un giro inesperado sin ti.",
  str_n32_multiline_7_name_desc = "Como Schwartz toma la oscuridad Angel en una batalla uno a uno, la rebelión está lista para comenzar, y el dragón está listo para emprender el vuelo, esta vez...",
  str_n32_multiline_8_name_desc = "Esta vez, Mia sobrevive ¿Alguien más tendría tanta suerte?",
  str_n32_multiline_9_name_desc = "—",
  str_n32_multiline_10_name_desc = "La tragedia todavía encuentra la manera de golpear, pero no tienes tiempo para detenerte y descansar.",
  str_n32_multiline_11_name_desc = "El plan para el último viaje en el tiempo está hecho. Ahora, comienza una carrera contra el tiempo.",
  str_n32_multiline_12_name_desc = "Ubicas la Oscuridad Angel, pero apaciguarla puede ser más difícil de lo esperado...",
  str_n32_multiline_13_name_desc = "El batir de las alas de una mariposa puede desencadenar un huracán. Pronto, todas sus piezas estarán alineadas.",
  str_n32_multiline_14_name_desc = "—",
  str_n32_multiline_15_name_desc = "Solo la Reina Blanca permanece en el tablero y se lo está jugando todo en un último movimiento desesperado.",
  str_n32_multiline_16_name_desc = "—",
  str_n32_multiline_17_name_desc = "Invitado al gran salón de Schwartz Mansión, escuchas a alguien hablando al otro lado de una puerta.",
  str_n32_multiline_18_name_desc = "Mientras te preparas para irte Schwartz Mansión, encuentras una pila de cartas quemadas en medio de un área cubierta de hierba en el jardín trasero...",
  str_n32_multiline_19_name_desc = "En un pequeño camino que conduce a Schwartz Mansion, una chica pelirroja de repente bloquea el camino de Sharona.",
  str_n32_multiline_20_name_desc = "Escondido cerca de la plaza central, sin querer escuchas una conversación entre dos viejos amigos.",
  str_n32_multiline_21_name_desc = "En una calle de Uptown, dos personas aparentemente sin relación están hablando de algo que merece tu atención...",
  str_n32_multiline_22_name_desc = "En un pequeño camino que conduce a Schwartz Mansión, una torre alta se derrumba con un estruendo...",
  str_n32_multiline_23_name_desc = "En medio del caos, descubres a dos nobles atrapados en el lugar.",
  str_n32_multiline_24_name_desc = "En un pequeño camino que conduce a Schwartz Mansión, una torre alta se ha derrumbado...",
  str_n32_multiline_1_name_desc_long = "Jakine ha fallado. No puedes dejar el Cristal de la Memoria Eterna, pero rastrear con éxito el tiempo antes de que comenzara el desfile. Joshua, que se ha convertido en un monstruo conocido como la Oscuridad Angel, te ataca una vez más. Después de luchar contra ella, intentas irte, a pesar de tu creciente desesperanza, pero sigues sin progresar. En este momento, otro Joshua aparece",
  str_n32_multiline_2_name_desc_long = "Joshua te explica toda la historia. Resulta que Joshua nunca murió, sino que se confinó a sí misma y a la personalidad incontrolable que se separó de su semilla al Cristal de la Eterna Memoria. Para ahorrar Joshua y abandonas este lugar, haces un plan para suprimir la Oscuridad Angel.",
  str_n32_multiline_3_name_desc_long = "Se dividen en dos grupos según el plan. Mia llega a las gradas, mientras que los demás atraen con éxito a la Oscuridad Angel afuera. Las cosas parecen ir a la perfección cuando la rebelión comienza temprano por razones desconocidas. Extraños enemigos y un dragón de aspecto extraño atacan las gradas, sumiendo tu plan en el caos.",
  str_n32_multiline_4_name_desc_long = "Derrotas a la Oscuridad Angel, pero la situación a tu alrededor se hunde cada vez más en la desesperación por segundos. Las fuerzas rebeldes, un dragón volador y una manía creciente se extienden continuamente entre la multitud, incluso transformando el rostro de Joshua en una imagen irreconocible de ferocidad. Tus compañeros son devorados por las fauces de la corrupción, uno tras otro, y así como tú te hundes en la desesperación, Jakine lanza el hechizo del viaje en el tiempo una vez más...",
  str_n32_multiline_5_name_desc_long = "El tiempo fluye hacia atrás, y todos en el jardín están nuevamente involucrados en la batalla con la Oscuridad. Angel. Solo tú sigues siendo perseguido por los guardias con sus espeluznantes expresiones... ¿Qué está pasando realmente aquí? Mientras te escondes, aferrándote a la querida vida, te pierdes en la contemplación.",
  str_n32_multiline_6_name_desc_long = "Similar a la primera vez que viajaste en el tiempo, todos se encuentran Joshua de nuevo, pero esta vez, parece que Schwartz y Joshua están en desacuerdo. Por esta razón, Caleb se queda de pie al lado de Jakine, y Schwartz se enfrenta a la oscuridad Angel solo.",
  str_n32_multiline_7_name_desc_long = "En la batalla uno a uno que siguió, Schwartz y la oscuridad Angel están igualados, pero la Oscuridad Angel de repente habla con la voz de Joshua, condenando el comportamiento irresponsable de Schwartz hacia su familia. Al mismo tiempo, comienza la rebelión y te das cuenta de que debes aprovechar la oportunidad para reagruparte con los demás. Sin embargo, es en este momento que eres testigo de la Oscuridad. Angel evitando que el dragón ataque las gradas.",
  str_n32_multiline_8_name_desc_long = "Esta vez, Mia sobrevive Sin embargo, joven Carleen se ve afectada debido a una lesión y elige quitarse la vida para proteger a su familia. El espíritu de Mia está a punto de derrumbarse por la situación, en ese momento, el Dark moribundo Angel acepta Mia en sus brazos y la abraza con fuerza. Es en este momento que Schwartz se convence de que la Oscuridad Angel es de hecho su esposa.",
  str_n32_multiline_9_name_desc_long = "en la mansión, Joshua explica la verdad a Caleb. Resulta que Joshua es una asesina de la facción opuesta a Schwartz y no la hermana biológica de Caleb. Ella trata de persuadir a Caleb para que la ayude a eliminar a los demás, y aunque Caleb no duda de la identidad de Joshua, él no está dispuesto a ayudarla y finalmente es asesinado por Joshua.",
  str_n32_multiline_10_name_desc_long = "Usted y Mia llega a la mansión para encontrar la residencia en un caos total, y con la ayuda de la Sra. Rot, logras escapar con Jakine. Aclara aproximadamente la verdad del asunto organizando la inteligencia obtenida a través de las excursiones de viaje en dos tiempos: este viaje en el tiempo será su última oportunidad.",
  str_n32_multiline_11_name_desc_long = "Esquivas a tus perseguidores según lo planeado y llegas antes Joshua Como lo planeado. Un nuevo juego de ajedrez está a punto de comenzar.",
  str_n32_multiline_12_name_desc_long = "Intentas aplacar a la Oscuridad Angel cantando la canción que ella le cantaba Mia. Esto recuerda a la Oscuridad Angel de su pasado, donde fracasó el intento de asesinato y fue conquistada por el joven Schwartz... Sus recuerdos son vívidos, lo que hace que sea aún más difícil para ella perdonar Schwartz.",
  str_n32_multiline_13_name_desc_long = "Schwartz no llega a ver la oscuridad Angel pero se encuentra con los soldados persiguiéndote. Guías a todos a las gradas antes de que el dragón ataque y te las arreglas para luchar contra él. Mia también ha consolado a la Oscuridad Angel, mientras que la Sra. Rot se queda con Joshua, y las cosas toman un cambio dramático para mejor.",
  str_n32_multiline_14_name_desc_long = "La verdad puede ser difícil de aceptar, pero para seguir avanzando, debemos aprender a enfrentarlo todo. Caleb, Schwartz, la oscuridad Angel, Mia, y Ms. Rot... A medida que se acerca la batalla final, todos tienen sus propias verdades firmemente grabadas en sus corazones.",
  str_n32_multiline_15_name_desc_long = "Libras una batalla decisiva contra el Demonio Blanco y la llevas al borde de la derrota. El Demonio Blanco tiene la intención de arrastrarte a la tumba con ella, mientras que el Demonio Oscuro Angel elige enfrentarse sola al Demonio Blanco después de reconciliarse con su familia. Los dos yo divididos finalmente se encuentran de nuevo.",
  str_n32_multiline_16_name_desc_long = "Dejas con éxito el Cristal de la Memoria Eterna después de guardar Joshua. Sin embargo, Joshua parece haber perdido todos sus recuerdos y elige emprender un nuevo viaje sola. Cuando es difícil afrontar el presente, las personas suelen optar por sumergirse en el pasado como vía de escape. Solo cuando las personas recuperen el coraje de vivir podremos avanzar hacia un nuevo futuro.",
  str_n32_multiline_17_name_desc_long = "—",
  str_n32_multiline_18_name_desc_long = "—",
  str_n32_multiline_19_name_desc_long = "—",
  str_n32_multiline_20_name_desc_long = "—",
  str_n32_multiline_21_name_desc_long = "—",
  str_n32_multiline_22_name_desc_long = "—",
  str_n32_multiline_23_name_desc_long = "—",
  str_n32_multiline_24_name_desc_long = "—",
  str_n32_multiline_doc_lock = "Avancemos con valentía. Tal vez tengamos algunos encuentros inesperados en el camino.",
  str_n32_multiline_doc_role_1 = "Srta. Blanc",
  str_n32_multiline_doc_role_2 = "Josué",
  str_n32_multiline_doc_role_3 = "Sharona",
  str_n32_multiline_doc_role_4 = "Otto",
  str_n32_multiline_doc_roledesc_1 = "El ex Capitán de la Guardia Nocturna, cuya edad es un misterio.\nFue herida y se retiró durante la Batalla de Umbraton en el año calendario matutino de 1988 después de ser asediada por Darkover, y más tarde se convirtió en una elegante guía turística.\nHasta el día de hoy, las leyendas de su identidad anterior—Ms. La podredumbre, portadora de muerte y destrucción, todavía persiste en los rincones silenciosos de Lumopolis...",
  str_n32_multiline_doc_roledesc_2 = "La hija de un erudito de renombre y la \"difunta esposa\" del Señor de la Ciudad. En ese entonces, bajo una inmensa presión, se enamoró y se casó Schwartz. Sin embargo, su padre no pudo ver el día de su boda, ya que murió en un incendio.\nEn Morning Calendar 1992, se anunció oficialmente que Joshua había fallecido a causa de una enfermedad.",
  str_n32_multiline_doc_roledesc_3 = "Nacida en Lumopolis, se le informó a una edad temprana que sus padres habían fallecido y quedó bajo el cuidado de los ancianos de la familia Kartima. En Morning Calendar 1988, Lumopolis busca a la familia Kartima por instigar un golpe de estado y Sharona por suerte logró escapar de la ciudad. Más tarde se unió a las fuerzas de la coalición para participar en un contraataque contra Darkover y, finalmente, se convirtió en comandante de la Legión Illumina.",
  str_n32_multiline_doc_roledesc_4 = "Nacido en la poderosa familia Troy, cuya principal esfera de influencia es el Consejo de Ancianos. Después de que el anterior Señor de la Ciudad fuera asesinado, los rumores comenzaron a señalar con el dedo a la familia Troy, pero estos rumores se disiparon rápidamente. Había planeado entrenar a su sobrina como su sucesora, sin embargo, más tarde fue registrada oficialmente como fallecida.",
  str_n32_multiline_doc_name_1 = "Antecedentes de la Sra. Blanc",
  str_n32_multiline_doc_name_2 = "Carta a los montagues",
  str_n32_multiline_doc_name_3 = "El cuento de la chica pelirroja",
  str_n32_multiline_doc_name_4 = "Roshee regresa al camino recto",
  str_n32_multiline_doc_name_5 = "La carta ardiente",
  str_n32_multiline_doc_name_6 = "La pelirroja y el anciano",
  str_n32_multiline_doc_name_7 = "Casa Montague",
  str_n32_multiline_doc_name_8 = "Doncella de la profecía",
  str_n32_multiline_doc_tips_1 = "Eventos pasados Antecedentes de la Sra. Blanc desbloqueados",
  str_n32_multiline_doc_tips_2 = "Eventos pasados Carta a los Montescos desbloqueada",
  str_n32_multiline_doc_tips_3 = "Eventos pasados El cuento de la chica pelirroja desbloqueado",
  str_n32_multiline_doc_tips_4 = "Eventos pasados Roshee regresa al camino recto desbloqueado",
  str_n32_multiline_doc_tips_5 = "Eventos pasados La carta ardiente desbloqueada",
  str_n32_multiline_doc_tips_6 = "Eventos pasados La chica pelirroja y el anciano desbloqueados",
  str_n32_multiline_doc_tips_7 = "Eventos pasados Casa Montague desbloqueada",
  str_n32_multiline_doc_tips_8 = "Eventos pasados Maiden of Prophecy desbloqueado",
  str_n32_multiline_doc_desc_1 = "Ms. Blanc es un pariente lejano de Lady Joshua, sin embargo, los dos no están relacionados por sangre. Ms. Blanc mostró un talento asombroso desde una edad temprana, pero sufrió la frustración de no tener ningún lugar donde poner su habilidad en buen uso. Ante la doble bendición de tener un hijo superdotado, sus padres no tuvieron más remedio que ponerla en manos de Caleb, pero fue después de esto que inesperadamente conoció a Lady Joshua. Los dos se llevaron bien, establecieron una fuerte relación y entablaron una animada conversación desde su primer encuentro. Como resultado, Joshua enseñó Ms. Blanc durante muchos años.",
  str_n32_multiline_doc_desc_2 = "En una pila de cartas quemadas se esconde una carta para el Niño de los Montescos, escrita por el padre de Caleb. En la carta, el padre de Caleb parece haber hecho una especie de resolución, ofreciendo sinceros deseos al destinatario.",
  str_n32_multiline_doc_desc_3 = "Una madre con Dragonkin despertó había dado a luz a dos hijas. Su herencia la hizo perder el control y su familia la mató. Para proteger a su dragón a punto de eclosionar, la hija mayor optó por vagar hasta instalarse en Umbraton. La hija menor creció sin saber que su madre había sido asesinada por su tribu.",
  str_n32_multiline_doc_desc_4 = "Aunque Otto no tiene hijos propios, siempre ha tratado a su sobrina Roshee, quien más tarde se convirtió en uno de los Cuatro Ángeles, Michael, como si fuera su propia hija. Cuando era más joven, Roshee solía disfrutar vagando por callejones y calles, atrapando ladrones y otros villanos variados, pero bajo la guía de Otto, gradualmente dirigió su mente a cosas más grandes. En el calendario matutino del año 1988, Roshee de repente se escapó de casa sin la menor advertencia.",
  str_n32_multiline_doc_desc_5 = "La razón por la que la sobrina de Otto, Roshee, se escapó de casa fue que recibió una nota que enumeraba todas las pruebas que indicaban que su tío Otto fue quien colocó Eclipsites en Lumopolis un año antes e instigó el levantamiento. Roshee no podía aceptar que esto fuera cierto, creyendo que su tío nunca haría tal cosa. Por lo tanto, Roshee dejó una carta para su amiga. Sharona, y decidió mantenerse alejada de su familia y unirse a la fuerza expedicionaria...",
  str_n32_multiline_doc_desc_6 = "La chica pelirroja derribó una torre alta en la que estaba encarcelado un anciano de la familia Kartima por ir en contra de Mime. Para sorpresa de la pelirroja, la anciana dijo lo mismo que había dicho su madre: \"Tú no eres quien salvará a la familia Kartima\". La chica pelirroja sabía que el mayor había estado esperando a su hermana. Sharona, pero sentía que esas cosas ya no le importaban.",
  str_n32_multiline_doc_desc_7 = "Pirro, Gautier... Montague. Estos son los nombres de las casas que se rebelaron contra el Schwartz familia—nombres que finalmente se perdieron en el tiempo. El odio cegó a los sobrevivientes, convirtiéndolos en los peones ideales para los posibles conspiradores.",
  str_n32_multiline_doc_desc_8 = "Sharona se encontró con el anciano al lado de la torre derrumbada. El anciano le dijo que, según la profecía, Sharona fue el único que pudo salvar a la familia Kartima. el deseaba Sharona heredar el Azure Flame Katana se transmite de generación en generación por los ancianos de la familia Kartima y, en última instancia, lleva la carga de asegurar la gloria futura de su linaje.",
  str_n32_multiline_doc_lockdesc_1 = "Cuando <color=#ffe062>Agrietamiento</color>, escucha lo que dice el guardia a la entrada del <color=#ffe062>sala de Schwartz Mansión</color>.",
  str_n32_multiline_doc_lockdesc_2 = "Cuando <color=#ffe062>Agrietamiento</color>, preste atención a lo que hay debajo de sus pies en su camino hacia el <color=#ffe062>plaza central</color>...",
  str_n32_multiline_doc_lockdesc_3 = "Cuando <color=#ffe062>Agrietamiento</color>, alguien parece estar bloqueando tu camino cuando sales del <color=#ffe062>plaza central</color>...",
  str_n32_multiline_doc_lockdesc_4 = "cuando las cosas empiezan <color=#ffe062>Muy lleno</color>, pareces poder escuchar algunos sonidos cuando te escondes alrededor del <color=#ffe062>plaza central</color>...",
  str_n32_multiline_doc_lockdesc_5 = "cuando las cosas empiezan <color=#ffe062>Muy lleno</color>, esté atento a figuras familiares cuando camine por los senderos alrededor del <color=#ffe062>plaza central</color>.",
  str_n32_multiline_doc_lockdesc_6 = "cuando las cosas empiezan <color=#ffe062>Muy lleno</color>, preste atención a las formas de los edificios al salir del <color=#ffe062>plaza central</color>.",
  str_n32_multiline_doc_lockdesc_7 = "cuando las cosas empiezan <color=#ffe062>Colapsando</color>, señalar una ruta de escape a dos nobles en el <color=#ffe062>plaza central</color>.",
  str_n32_multiline_doc_lockdesc_8 = "cuando las cosas empiezan <color=#ffe062>Colapsando</color>, preste atención a la torre que se derrumba al salir de la <color=#ffe062>plaza central</color>.",
  str_n32_multiline_doc_unlock_1 = "Hacer Ms. Blanc y dama Joshua compartir tal historia?!",
  str_n32_multiline_doc_unlock_2 = "¡¿Cómo pudo el padre de Caleb haber escrito una carta así?!",
  str_n32_multiline_doc_unlock_3 = "¿Es la historia de la chica pelirroja realmente solo un cuento?",
  str_n32_multiline_doc_unlock_4 = "Parece que Otto también tiene sus inesperadas debilidades...",
  str_n32_multiline_doc_unlock_5 = "¿La sobrina se escapó de casa por lo que hizo Otto?",
  str_n32_multiline_doc_unlock_6 = "La chica pelirroja es en realidad la hermana biológica de Sharona, Leona?!",
  str_n32_multiline_doc_unlock_7 = "Esos nombres ahora perdidos en el tiempo... ¿No te parecen familiares?",
  str_n32_multiline_doc_unlock_8 = "Sharona finalmente conoció a la persona que la había estado esperando...",
  str_n32_multiline_lock_tips1 = "No tengo ninguna pista todavía.",
  str_n32_multiline_lock_tips2 = "Ve y busca la ubicación indicada.",
  str_n32_multiline_desc_1 = "El pasado ha sido reiniciado. El cristal espera tu decisión.",
  str_n32_multiline_desc_2 = "Sigue yendo y viniendo hasta que recuperes la verdad en la destrucción.",
  str_n32_multiline_desc_3 = "Descubra dónde terminan la luz y la oscuridad al hacer su elección final.",
  str_n32_multiline_desc_pass = "Embárcate en un viaje. Siempre recordaremos la oda cantada a la ciudad en el cielo.",
  str_n32_multiline_name_1 = "Agrietamiento",
  str_n32_multiline_name_2 = "Muy lleno",
  str_n32_multiline_name_3 = "Colapsando",
  str_n32_multiline_main_forlder_pass = "El restablecimiento actual ha finalizado",
  str_n32_multiline_main_folder_unpass = "El tiempo se está reiniciando",
  str_n32_multiline_branch_folder_pass = "Experimentado todos los encuentros",
  str_n32_multiline_branch_folder_unpass_normal = "Todavía hay encuentros que has <color=#fea62d>omitido</color>.",
  str_n32_multiline_branch_folder_unpass_format = "Te lo perdiste <color=#fea62d>{1}</color> encuentro(s).",
